module.exports = {
 meta: {width:1280,height:720,fps:30,duration:2,title:"Cloud Render Benchmark"},
 render(ctx,t,w,h) {
  const p=t/2; const ease=p*p*(3-2*p);
  ctx.fillStyle="#111322"; ctx.fillRect(0,0,w,h);
  ctx.fillStyle="#d9cdf0"; ctx.font="bold "+w/24+"px sans-serif"; ctx.textAlign="center";
  ctx.fillText("CLOUD RENDER BENCHMARK",w/2,h*.35);
  ctx.fillStyle="#29243a"; ctx.fillRect(w*.15,h*.5,w*.7,h*.05);
  ctx.fillStyle="#9955ff"; ctx.fillRect(w*.15,h*.5,w*.7*ease,h*.05);
  ctx.beginPath(); ctx.arc(w*.15+w*.7*ease,h*.7,h*.04,0,Math.PI*2); ctx.fillStyle="#55ddcc"; ctx.fill();
 }
};
